//! Checker relations typescript-eslint rules read beyond rendered type text:
//! type identity, flags of union parts, base constraints, contextual types,
//! assignability and resolved signatures. Every reply mirrors one query the
//! typescript-eslint rule makes against its own `TypeChecker`.
use corsa::api::{NodeHandle, ProjectSession, TypeResponse};
use vize_l0::{FxHashMap, FxHashSet, String as CompactString};

mod checker;
mod contextual;
mod deprecation;
mod unchanged;

use checker::Checker;
pub(in crate::linter) use checker::flags;

/// Half-open generated byte range of one syntax node.
pub(in crate::linter) type Span = (u32, u32);

/// Everything one script asks the checker for.
#[derive(Default)]
pub(in crate::linter) struct RelationRequest {
    pub assertions: Vec<AssertionAsk>,
    pub non_null: Vec<NonNullAsk>,
    pub shapes: Vec<Span>,
    pub returns: Vec<ReturnAsk>,
    /// `isTypeAssignableTo(typeAt(source), typeAt(target))`.
    pub assignable: Vec<(Span, Span)>,
    pub deprecations: Vec<DeprecationAsk>,
    /// `no-unnecessary-type-arguments`: whether a type argument is its type
    /// parameter's default (`(argument, default)`).
    pub defaults: Vec<(Span, Span)>,
}

/// Replies aligned with the request lists.
#[derive(Default)]
pub(in crate::linter) struct RelationReply {
    pub assertions: Vec<AssertionReply>,
    pub non_null: Vec<NonNullReply>,
    pub shapes: Vec<Option<Shape>>,
    pub returns: Vec<ReturnReply>,
    pub assignable: Vec<Option<bool>>,
    pub deprecations: Vec<Option<Deprecation>>,
    pub defaults: Vec<Option<bool>>,
}

/// How the operand of an assertion reads as a literal (`isConceptuallyLiteral`).
#[derive(Clone, Copy, PartialEq, Eq)]
pub(in crate::linter) enum Literal {
    /// Not a literal-like expression.
    No,
    /// An object literal; `empty` when it has no properties.
    Object { empty: bool },
    /// Any other literal-like expression (array, template, function, class...).
    Other,
}

/// `x as T` / `<T>x`.
pub(in crate::linter) struct AssertionAsk {
    pub node: Span,
    pub expression: Span,
    /// The innermost non-assertion operand when the operand is an assertion.
    pub original: Option<Span>,
    /// The annotation is an intersection type node.
    pub intersection: bool,
    pub literal: Literal,
    /// Callee of an immediately invoked function operand, and whether it
    /// declares a return type.
    pub iife: Option<(Span, bool)>,
    pub context: AssertionContext,
}

/// The syntax half of the contextual check (`shouldSkipContextualTypeFallback`
/// and `isContextuallyUnnecessary`).
pub(in crate::linter) struct AssertionContext {
    /// A syntactic reason to skip the contextual type for a non-`any` cast.
    pub skip: bool,
    /// The parent is an assertion, spread or `satisfies`.
    pub skip_parent: bool,
    pub parent_logical: bool,
    pub parent_property: bool,
    /// The innermost operand is literal-like (`isConceptuallyLiteral`).
    pub literal_original: bool,
    /// Callees whose generic signature makes this a generic context.
    pub generic_callees: Vec<Span>,
    /// The callee and argument index when the assertion is a call argument.
    pub overload: Option<(Span, usize)>,
    pub call_argument: bool,
    /// The object literal the assertion is a property value of.
    pub property: Option<PropertyContext>,
    /// The operand is `null` or `undefined`.
    pub nullish_literal: bool,
    pub const_assertion: bool,
    /// `isImplicitlyNarrowedLiteralDeclaration`, for `wouldSameTypeBeInferred`.
    pub narrowed_declaration: bool,
}

pub(in crate::linter) struct PropertyContext {
    pub object: Span,
    /// The object (or a call it is passed to) is checked with `satisfies`.
    pub satisfies: bool,
}

#[derive(Clone, Default)]
pub(in crate::linter) struct AssertionReply {
    /// The cast type is a literal type (`isTypeLiteral`).
    pub cast_is_literal: bool,
    /// `isTypeUnchanged(uncast, cast)`.
    pub unchanged: bool,
    /// `isTypeUnchanged(original, cast)` for `x as A as B`, false when the
    /// cast is `any`.
    pub double_unchanged: bool,
    /// The receiver's contextual type already accepts the operand.
    pub contextually_unnecessary: bool,
    /// `x as any as T` where the receiver already accepts `x`.
    pub double_contextual: bool,
}

/// Where typescript-eslint's `getContextualType` util reads a type.
#[derive(Clone, Copy)]
pub(in crate::linter) enum ContextSource {
    /// `checker.getContextualType(node)`.
    Checker(Span),
    /// `checker.getTypeAtLocation(node)`: an assignment target, or the name of
    /// an annotated declaration (its declared type).
    TypeAt(Span),
}

/// `x!`.
pub(in crate::linter) struct NonNullAsk {
    pub expression: Span,
    pub context: Option<ContextSource>,
    /// Name of the operand's annotated `let`/`var` declaration when it has no
    /// initializer or definite assignment (`isPossiblyUsedBeforeAssigned`):
    /// the checker types a declaration name with its declared type.
    pub declared: Option<Span>,
}

#[derive(Clone, Default)]
pub(in crate::linter) struct NonNullReply {
    /// The checker typed the operand at all.
    pub typed: bool,
    /// Union-part flags of the operand type.
    pub actual: u32,
    /// Union-part flags of the operand's base-constrained type.
    pub constrained: u32,
    /// The constrained type is not the operand type itself.
    pub constrained_differs: bool,
    /// Union-part flags of the contextual type, when there is one.
    pub contextual: Option<u32>,
    /// The declared type is the operand's constrained type.
    pub declared_matches: bool,
}

/// Union/intersection structure of a base-constrained type.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub(in crate::linter) struct Shape {
    pub flags: u32,
    pub union: bool,
    pub intersection: bool,
    pub array: bool,
    pub tuple: bool,
    /// The type has a `number` index signature.
    pub number_index: bool,
    /// The type has a `length` property of a number-like type.
    pub number_length: bool,
    pub parts: Vec<Shape>,
}

/// A deprecated use.
#[derive(Clone)]
pub(in crate::linter) struct Deprecation {
    /// The `@deprecated` tag text; empty when the tag gives no reason.
    pub reason: CompactString,
    /// The property name a computed key or element access resolved to.
    pub name: Option<CompactString>,
}

/// One use typescript-eslint's `no-deprecated` checks.
pub(in crate::linter) struct DeprecationAsk {
    /// The identifier (or `super`) the symbol is read at.
    pub node: Span,
    pub kind: DeprecationKind,
}

pub(in crate::linter) enum DeprecationKind {
    /// `searchForDeprecationInAliasesChain(getSymbolAtLocation(node), true)`.
    Symbol,
    /// The exported name of an export specifier; skipped when the alias
    /// itself carries the tag.
    ExportAlias,
    /// The callee of a call-like node (`getCallLikeDeprecation`).
    CallLike { call: Span },
    /// An identifier whose parent is an object literal or pattern property.
    ObjectProperty { object: Span, name: CompactString },
    /// An object literal key checked against the literal's contextual type;
    /// `key` is the computed key expression when `name` is not static.
    ContextualProperty {
        object: Span,
        name: Option<CompactString>,
        key: Option<Span>,
    },
    /// `object[literal]`.
    Member { object: Span, property: Span },
}

/// `prefer-return-this-type`: a class method's returned expressions.
pub(in crate::linter) struct ReturnAsk {
    pub class: Span,
    pub expressions: Vec<Span>,
}

#[derive(Clone, Default)]
pub(in crate::linter) struct ReturnReply {
    /// Some expression's type is the class instance type, or a union with it.
    pub class_type: bool,
    /// Some expression's type is the class `this` type.
    pub this_type: bool,
}

impl RelationReply {
    /// The reply that keeps every rule silent: nothing could be resolved.
    pub(super) fn empty(request: &RelationRequest) -> Self {
        Self {
            assertions: vec![AssertionReply::default(); request.assertions.len()],
            non_null: vec![NonNullReply::default(); request.non_null.len()],
            shapes: vec![None; request.shapes.len()],
            returns: vec![ReturnReply::default(); request.returns.len()],
            assignable: vec![None; request.assignable.len()],
            deprecations: vec![None; request.deprecations.len()],
            defaults: vec![None; request.defaults.len()],
        }
    }
}

/// Every node span `request` needs typed, translated and deduplicated, so the
/// expression batch resolves each handle and type once.
pub(super) fn spans(request: &RelationRequest, translate: &dyn Fn(Span) -> Span) -> Vec<Span> {
    let mut seen = FxHashSet::default();
    let mut order = Vec::new();
    let mut add = |span: Span| {
        let span = translate(span);
        if span.0 < span.1 && seen.insert(span) {
            order.push(span);
        }
    };
    for ask in &request.assertions {
        add(ask.node);
        add(ask.expression);
        for callee in &ask.context.generic_callees {
            add(*callee);
        }
        if let Some((callee, _)) = ask.context.overload {
            add(callee);
        }
        if let Some(property) = &ask.context.property {
            add(property.object);
        }
        if let Some(original) = ask.original {
            add(original);
        }
        if let Some((callee, _)) = ask.iife {
            add(callee);
        }
    }
    for ask in &request.non_null {
        add(ask.expression);
        if let Some(ContextSource::Checker(span) | ContextSource::TypeAt(span)) = ask.context {
            add(span);
        }
        if let Some(declared) = ask.declared {
            add(declared);
        }
    }
    for span in &request.shapes {
        add(*span);
    }
    for ask in &request.returns {
        add(ask.class);
        for expression in &ask.expressions {
            add(*expression);
        }
    }
    for (source, target) in &request.assignable {
        add(*source);
        add(*target);
    }
    for (argument, default) in &request.defaults {
        add(*argument);
        add(*default);
    }
    for ask in &request.deprecations {
        add(ask.node);
        match &ask.kind {
            DeprecationKind::Symbol | DeprecationKind::ExportAlias => {}
            DeprecationKind::CallLike { call } => add(*call),
            DeprecationKind::ObjectProperty { object, .. } => add(*object),
            DeprecationKind::ContextualProperty { object, key, .. } => {
                add(*object);
                if let Some(key) = key {
                    add(*key);
                }
            }
            DeprecationKind::Member { object, property } => {
                add(*object);
                add(*property);
            }
        }
    }
    order
}

pub(super) struct Located {
    handles: FxHashMap<Span, NodeHandle>,
    types: FxHashMap<Span, TypeResponse>,
}

impl Located {
    pub(super) fn handle(&self, span: Span) -> Option<&NodeHandle> {
        self.handles.get(&span)
    }

    pub(super) fn ty(&self, span: Span) -> Option<&TypeResponse> {
        self.types.get(&span)
    }
}

/// Answer `request` from the expression batch's located `spans`.
pub(super) async fn answer(
    session: &ProjectSession,
    request: &RelationRequest,
    translate: &dyn Fn(Span) -> Span,
    spans: Vec<Span>,
    handles: Vec<NodeHandle>,
    types: Vec<Option<TypeResponse>>,
) -> RelationReply {
    let mut located = Located {
        handles: FxHashMap::default(),
        types: FxHashMap::default(),
    };
    for ((span, handle), ty) in spans.into_iter().zip(handles).zip(types) {
        located.handles.insert(span, handle);
        if let Some(ty) = ty {
            located.types.insert(span, ty);
        }
    }
    let mut checker = Checker::new(session);
    let mut reply = RelationReply::default();
    for ask in &request.assertions {
        reply
            .assertions
            .push(assertion(&mut checker, &located, ask, translate).await);
    }
    for ask in &request.non_null {
        reply
            .non_null
            .push(non_null(&mut checker, &located, ask, translate).await);
    }
    for span in &request.shapes {
        let shape = match located.ty(translate(*span)) {
            Some(ty) => checker.shape(ty).await,
            None => None,
        };
        reply.shapes.push(shape);
    }
    for ask in &request.returns {
        reply
            .returns
            .push(returns(&mut checker, &located, ask, translate).await);
    }
    for (source, target) in &request.assignable {
        let value = match (
            located.ty(translate(*source)),
            located.ty(translate(*target)),
        ) {
            (Some(source), Some(target)) => Some(checker.assignable(source, target).await),
            _ => None,
        };
        reply.assignable.push(value);
    }
    for (argument, default) in &request.defaults {
        let value = match (
            located.ty(translate(*argument)),
            located.ty(translate(*default)),
        ) {
            // A bare name in type position can type as the error type; two
            // of those are not proof the argument is the default.
            (Some(argument), Some(default))
                if (argument.flags | default.flags) & flags::ANY == 0 =>
            {
                Some(checker.same_type(argument, default).await)
            }
            _ => None,
        };
        reply.defaults.push(value);
    }
    if !request.deprecations.is_empty() {
        let nodes = request
            .deprecations
            .iter()
            .filter_map(|ask| located.handle(translate(ask.node)).cloned())
            .collect::<Vec<_>>();
        let mut symbols = checker.symbols_at(nodes).await.into_iter();
        for ask in &request.deprecations {
            let symbol = if located.handle(translate(ask.node)).is_some() {
                symbols.next().flatten()
            } else {
                None
            };
            reply
                .deprecations
                .push(deprecation::check(&mut checker, &located, ask, symbol, translate).await);
        }
    }
    reply
}

async fn assertion(
    checker: &mut Checker<'_>,
    located: &Located,
    ask: &AssertionAsk,
    translate: &dyn Fn(Span) -> Span,
) -> AssertionReply {
    let Some(cast) = located.ty(translate(ask.node)).cloned() else {
        return AssertionReply::default();
    };
    let mut reply = AssertionReply {
        cast_is_literal: cast.flags & flags::LITERAL != 0,
        ..AssertionReply::default()
    };
    let uncast = match ask.iife {
        Some((callee, annotated)) => match located.ty(translate(callee)) {
            Some(callee) => checker.iife_return(callee, annotated).await,
            None => None,
        },
        None => located.ty(translate(ask.expression)).cloned(),
    };
    let Some(uncast) = uncast else {
        return reply;
    };
    reply.unchanged =
        unchanged::is_type_unchanged(checker, ask.intersection, ask.literal, &uncast, &cast).await;
    let would_same_type_be_inferred = if reply.cast_is_literal {
        ask.context.narrowed_declaration
    } else {
        !ask.context.const_assertion
    };
    if reply.unchanged && would_same_type_be_inferred {
        return reply;
    }
    let contextual =
        contextual::fallback_type(checker, located, ask, &cast, &uncast, translate).await;
    if let Some(contextual) = &contextual {
        reply.contextually_unnecessary = contextual::is_contextually_unnecessary(
            checker, ask, &cast, &uncast, contextual, located, translate,
        )
        .await;
        if reply.contextually_unnecessary {
            return reply;
        }
    }
    let Some(original) = ask.original.and_then(|span| located.ty(translate(span))) else {
        return reply;
    };
    // `isTypeUnchanged(node, innerExpression, ...)`: the inner assertion is
    // never a literal.
    reply.double_unchanged = cast.flags & flags::ANY == 0
        && unchanged::is_type_unchanged(checker, ask.intersection, Literal::No, original, &cast)
            .await;
    if !reply.double_unchanged
        && let Some(contextual) = &contextual
    {
        // The intermediate type is the inner assertion's: the uncast type.
        reply.double_contextual = uncast.flags & (flags::ANY | flags::UNKNOWN) != 0
            && checker.assignable(original, contextual).await;
    }
    reply
}

async fn non_null(
    checker: &mut Checker<'_>,
    located: &Located,
    ask: &NonNullAsk,
    translate: &dyn Fn(Span) -> Span,
) -> NonNullReply {
    let Some(actual) = located.ty(translate(ask.expression)).cloned() else {
        return NonNullReply::default();
    };
    let actual_flags = checker.union_flags(&actual).await;
    // Only instantiable types (and compositions of them) have a base
    // constraint other than themselves; skip the round-trip for the rest.
    let constrained = if (actual.flags | actual_flags) & flags::INSTANTIABLE != 0 {
        checker
            .base_constraint(&actual)
            .await
            .unwrap_or_else(|| actual.clone())
    } else {
        actual.clone()
    };
    let constrained_flags = if constrained.id == actual.id {
        actual_flags
    } else {
        checker.union_flags(&constrained).await
    };
    let mut reply = NonNullReply {
        typed: true,
        actual: actual_flags,
        constrained: constrained_flags,
        constrained_differs: constrained.id != actual.id,
        contextual: None,
        declared_matches: false,
    };
    if (actual_flags | constrained_flags) & flags::NULLABLE == 0 {
        if let Some(declared) = ask.declared.and_then(|span| located.ty(translate(span))) {
            reply.declared_matches = declared.id == constrained.id;
        }
        return reply;
    }
    if reply.constrained_differs {
        return reply;
    }
    let contextual = match ask.context {
        Some(ContextSource::Checker(span)) => match located.handle(translate(span)) {
            Some(handle) => checker.contextual(handle).await,
            None => None,
        },
        Some(ContextSource::TypeAt(span)) => located.ty(translate(span)).cloned(),
        None => None,
    };
    if let Some(contextual) = contextual {
        reply.contextual = Some(checker.union_flags(&contextual).await);
    }
    reply
}

async fn returns(
    checker: &mut Checker<'_>,
    located: &Located,
    ask: &ReturnAsk,
    translate: &dyn Fn(Span) -> Span,
) -> ReturnReply {
    let mut reply = ReturnReply::default();
    let Some(class) = located.ty(translate(ask.class)).cloned() else {
        return reply;
    };
    // The class node may type as the constructor or the instance; both carry
    // the class symbol, as do its instance type and its `this` type.
    let Some(class_symbol) = class.symbol.clone() else {
        return reply;
    };
    let is_instance = |ty: &TypeResponse| {
        ty.id == class.id
            || (ty.flags & flags::OBJECT != 0 && ty.symbol.as_ref() == Some(&class_symbol))
    };
    for span in &ask.expressions {
        let Some(ty) = located.ty(translate(*span)) else {
            continue;
        };
        if ty.flags & flags::TYPE_PARAMETER != 0 && ty.symbol.as_ref() == Some(&class_symbol) {
            reply.this_type = true;
            continue;
        }
        if is_instance(ty) {
            reply.class_type = true;
            continue;
        }
        if ty.flags & flags::UNION != 0 && checker.parts(ty).await.iter().any(is_instance) {
            reply.class_type = true;
        }
    }
    reply
}
